// 存量迁移：SQLite messages → SDK JSONL session 文件。
// 只迁 text/thinking/toolCall/toolResult 文本；不迁 autoGenerated/usage/图片/附件（spec §7）。
// 幂等：pi_session_file 非空即跳过。跑法：node scripts/migrate-messages-to-jsonl.mjs <dbPath> <dataRoot>
import path from "node:path";
import { mkdirSync, existsSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";
import { SessionManager } from "@earendil-works/pi-coding-agent";

const ZERO_USAGE = {
  input: 0,
  output: 0,
  cacheRead: 0,
  cacheWrite: 0,
  totalTokens: 0,
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
};

// 旧 autoGenerated 标记：content 首块为 "__autoGenerated__" 文本块（存量丢弃）。
function isAutoGeneratedRow(contentJson) {
  try {
    const blocks = JSON.parse(contentJson);
    return (
      Array.isArray(blocks) &&
      blocks[0]?.type === "text" &&
      blocks[0]?.text === "__autoGenerated__"
    );
  } catch {
    return false;
  }
}

function blockToPi(block) {
  switch (block.type) {
    case "text":
      return { type: "text", text: block.text };
    case "thinking":
      return { type: "thinking", thinking: block.thinking };
    case "tool_use":
      return {
        type: "toolCall",
        id: block.id,
        name: block.name,
        arguments: block.input ?? {},
      };
    case "image":
      return {
        type: "image",
        data: block.source?.data ?? "",
        mimeType: block.source?.media_type ?? "image/png",
      };
    default:
      return null;
  }
}

// deskwand 的 tool_result 存为独立 assistant 行（content 只含一个 tool_result 块），
// pi 则存为独立 toolResult message —— 此处按行拆分。
function rowToPiMessages(row) {
  let blocks;
  try {
    blocks = JSON.parse(row.content);
  } catch {
    blocks = [];
  }
  if (!Array.isArray(blocks)) blocks = [];

  if (row.role === "user") {
    return [
      {
        role: "user",
        content: blocks.map(blockToPi).filter(Boolean),
        timestamp: row.timestamp,
      },
    ];
  }
  if (row.role === "assistant") {
    const toolResult = blocks.find((b) => b.type === "tool_result");
    if (toolResult && blocks.length === 1) {
      return [
        {
          role: "toolResult",
          toolCallId: toolResult.toolUseId ?? "",
          toolName: "tool",
          content: [{ type: "text", text: toolResult.content ?? "" }],
          isError: Boolean(toolResult.isError),
          timestamp: row.timestamp,
        },
      ];
    }
    return [
      {
        role: "assistant",
        content: blocks.map(blockToPi).filter(Boolean),
        timestamp: row.timestamp,
        usage: { ...ZERO_USAGE },
        api: "openai-completions",
        provider: "migrated",
        model: "migrated",
        stopReason: "stop",
      },
    ];
  }
  // system 等其他角色跳过
  return [];
}

function migrateSession(db, session, dataRoot) {
  const sessionId = String(session.id);
  if (session.pi_session_file) return { sessionId, skipped: true };
  const rows = db
    .prepare(
      "SELECT role, content, timestamp FROM messages WHERE session_id = ? ORDER BY timestamp ASC",
    )
    .all(sessionId)
    .filter((r) => !isAutoGeneratedRow(r.content));
  if (rows.length === 0) return { sessionId, skipped: true };

  const sessionDir = path.join(dataRoot, "sessions", sessionId);
  if (!existsSync(sessionDir)) {
    mkdirSync(sessionDir, { recursive: true });
  }
  const sm = SessionManager.create(session.cwd ?? process.cwd(), sessionDir, {
    id: sessionId,
  });
  for (const row of rows) {
    for (const msg of rowToPiMessages(row)) {
      sm.appendMessage(msg);
    }
  }
  return { sessionId, sessionFile: sm.getSessionFile() };
}

function main() {
  const [dbPath, dataRoot] = process.argv.slice(2);
  if (!dbPath || !dataRoot) {
    console.error(
      "usage: node scripts/migrate-messages-to-jsonl.mjs <dbPath> <dataRoot>",
    );
    process.exit(1);
  }
  const db = new DatabaseSync(dbPath, { enableForeignKeyConstraints: true });
  const sessions = db
    .prepare("SELECT id, pi_session_file, cwd FROM sessions")
    .all();
  let migrated = 0;
  let skipped = 0;
  for (const s of sessions) {
    const r = migrateSession(db, s, dataRoot);
    if (r.skipped) skipped += 1;
    else migrated += 1;
    console.log(
      `[migrate] ${r.sessionId}: ${r.skipped ? "skipped" : `-> ${r.sessionFile}`}`,
    );
  }
  db.close();
  console.log(`[migrate] done: ${migrated} migrated, ${skipped} skipped`);
}

main();
